package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_SimpleValue() {
        byte[] buffer = "0000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        assertEquals(83L, result); // 123 in octal is 83 decimal
    }

    @Test
    public void testParseOctal_WithLeadingZerosAndSpaces() {
        // Testing leading spaces and zeros
        byte[] buffer = "   000755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        assertEquals(493L, result); // 755 octal is 493 decimal
    }

    @Test
    public void testParseOctal_WithTrailingNull() {
        // Testing the break condition for currentByte == 0
        byte[] buffer = new byte[10];
        buffer[0] = '0';
        buffer[1] = '1';
        buffer[2] = 0; // NUL terminator
        buffer[3] = '2';
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        assertEquals(1L, result);
    }

    @Test
    public void testParseOctal_WithTrailingSpaceAfterDigits() {
        // Testing the break condition when a space is encountered after stillPadding is false
        byte[] buffer = "0123 456".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        assertEquals(83L, result); // 123 octal is 83 decimal
    }

    @Test
    public void testParseOctal_OnlyPadding() {
        // Testing buffer containing only spaces or zeros
        byte[] buffer = "   000".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        assertEquals(0L, result);
    }

    @Test
    public void testParseOctal_OffsetAndLength() {
        // Testing that offset and length are respected
        byte[] buffer = "ABC00010DEF".getBytes();
        // Start at index 3 ('0'), process 3 bytes ('001')
        long result = TarUtils.parseOctal(buffer, 3, 3);
        assertEquals(1L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        // Testing exception when byte is not 0-7 (e.g., '8')
        byte[] buffer = "0008".getBytes();
        TarUtils.parseOctal(buffer, 0, buffer.length);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidChar() {
        // Testing exception when byte is a non-octal character (e.g., 'A')
        byte[] buffer = "000A".getBytes();
        TarUtils.parseOctal(buffer, 0, buffer.length);
    }

    @Test
    public void testParseOctal_EmptyBuffer() {
        byte[] buffer = new byte[0];
        long result = TarUtils.parseOctal(buffer, 0, 0);
        assertEquals(0L, result);
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Testing maximum possible 63-bit value (octal 777777777777777777)
        byte[] buffer = "777777777777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        // Calculation: 8^18 - 1 is too big for long, but the logic handles up to sign bit
        // Let's use a safe large octal
        byte[] buffer2 = "777777777777".getBytes();
        long result2 = TarUtils.parseOctal(buffer2, 0, buffer2.length);
        // 777777777777 octal = 549755813887 decimal
        assertEquals(549755813887L, result2);
    }
}
